import os,pathlib,sys
workspace=pathlib.Path(os.environ["ORDIVON_EVAL_WORKSPACE"]); sys.path.insert(0,str(workspace))
from allocation_001 import distribute_units_001,preview_floor_001
def ref(total,weights):
    wt=sum(weights); out=[(total*w)//wt for w in weights]; rem=total-sum(out); order=sorted(range(len(weights)),key=lambda i:(-(total*weights[i]%wt),i))
    for i in order[:rem]: out[i]+=1
    return out
for total in range(0,57):
    for weights in ([1],[1,1],[2,3,5],[3,3,3,3],[3,7,3,5],[11,13,17,19,23]): assert distribute_units_001(total,list(weights))==ref(total,list(weights))
assert preview_floor_001(7,[1,1,1])==[2,2,2]
w=[2,7,3,5]; before=list(w); out=distribute_units_001(997,w); assert w==before and sum(out)==997
for args in ((-1,[1]),(True,[1]),(1,[]),(1,[0]),(1,[False]),(1,[1.5])):
    try: distribute_units_001(*args)
    except ValueError: pass
    else: raise SystemExit("invalid input accepted")

